def grad(self, xs, ys):
        """Computes the gradients of the network."""
        return self.sess.run(
            self.cross_entropy_grads, feed_dict={
                self.x: xs,
                self.y_: ys
            })

def grad(self, xs, ys):
        """Computes the gradients of the network."""
        grads = {}
        for x, y in zip(xs, ys):
            for i in range(self.n):
                grads[i] = grads[i] + self.loss(x, y) * self.layers[i].grad(x, y)
        return grads

