def CheckProg(context, prog_name):
    """Simple check if a program exists in the path.  Returns the path
    for the application, or None if not found.
    """
    if context.platform == 'win32':
        # Assume we're using the Windows shell.
        # We need to quote the program name if it contains spaces.
        if ' ' in prog_name:
            prog_name = '"%s"' % prog_name

        # Use the shell to check if the program exists.
        # Note that the shell must be available, and we need to
        # use the "where" command to find the path to the program.
        # The "where" command is part of the "find" command.
        check_command = "where %s" % prog_name
        (rc, output) = context.RunShell(check_command, shell=True)
        if rc == 0:
            # The program exists, so return the path to the program.
            return output.strip()
        else:
            # The program does not exist.
            return None

    else:
        # Assume we're using a Unix shell.
        # Use the shell to check if the program exists.
        check_command = "which %s" % prog_name
        (rc, output) = context.RunShell(check_command, shell=True)
        if rc == 0:
            # The program exists, so return the path to the program.
            return output.strip()
        else:
            # The program does not exist.
            return None

