def _get_str_range(self, vals_stats):
        """Return a string containing the range of values."""
        minmax = vals_stats[1] # stats minmax
        minval = self.fmtstr.format(minmax[0])
        maxval = self.fmtstr.format(minmax[1])
        return '{A} to {B:6>}'.format(A=minval, B=maxval)

def _get_str_range(self, vals_stats):
        """Return a string containing the range of values."""
        if vals_stats is None:
            return "Unknown"
        min_val = vals_stats.get("min")
        max_val = vals_stats.get("max")
        if min_val is None:
            min_val = "Unknown"
        if max_val is None:
            max_val = "Unknown"
        return "{} to {}".format(min_val, max_val)

def pop(self, name):
        """Get and remove key from database (atomic)."""
        self.lock.acquire()
        try:
            if name in self.data:
                return self.data.pop(name)
            else:
                return None
        finally:
            self.lock.release()

