def pulse(time, start, duration):
    """ Implements vensim's PULSE function

    In range [-inf, start) returns 0
    In range [start, start + duration) returns 1
    In range [start + duration, +inf] returns 0
    """
    if time < start:
        return 0
    elif time < start + duration:
        return 1
    else:
        return 0

def forget(self):
