def get_components(self, other):
        """ Break this vector into one vector that is perpendicular to the 
        given vector and another that is parallel to it. """
        if self.is_zero():
            raise ValueError("Cannot decompose a zero vector.")
        if other.is_zero():
            raise ValueError("Cannot decompose a vector in a zero vector.")
        if self.is_parallel(other):
            raise ValueError("Cannot decompose a vector in a parallel vector.")
        if self.is_anti_parallel(other):
            raise ValueError("Cannot decompose a vector in an anti-parallel vector.")
        # TODO: Decompose vector in perpendicular and parallel vectors.
        # https://www.youtube.com/watch?v=t_7RRkVg1W8
        return None

def validate(self, value):
        """Return a boolean if the value is valid"""
        try:
            self._choice = IPAddress(value)
            return True
        except (ValueError, AddrFormatError):
            self.error_message = '%s is not a valid IP address.' % value
            return False

def validate(self, value):
        """Return a boolean if the value is valid"""
        if value is not None:
            if not isinstance(value, int):
                raise ValueError(
                    "This field must be an integer."
                )

            if not value >= 0:
                raise ValueError(
                    "This field must be greater than or equal to 0."
                )

        return True

def _matmul_with_relative_keys_2d(x, y, heads_share_relative_embedding):
  """Helper function for dot_product_unmasked_self_attention_relative_2d."""
  if heads_share_relative_embedding:
    ret = tf.einsum("bhxyd,md->bhxym", x, y)
  else:
    ret = tf.einsum("bhxyd,hmd->bhxym", x, y)
  return ret

