async def release(self) -> None:
        """Like read(), but reads all the data to the void."""
        if self._at_eof:
            return
        while not self._at_eof:
            await self.read_chunk(self.chunk_size)

async def release(self) -> None:
        """Like read(), but reads all the data to the void."""
        while True:
            data = self.read(self.buffer_size)
            if not data:
                break

def compress(self, data_list):
        """
        Return the cleaned_data of the form, everything should already be valid
        """
        data = {}
        if data_list:
            return dict(
                (f.name, data_list[i]) for i, f in enumerate(self.form))
        return data

def compress(self, data_list):
        """
        Return the cleaned_data of the form, everything should already be valid
        """
        data = {}
        for key in data_list.keys():
            if data_list[key]:
                if isinstance(data_list[key], list):
                    data[key] = [x.strip() for x in data_list[key]]
                else:
                    data[key] = data_list[key].strip()
        return data

