def warmup(f):
    """ Decorator to run warmup before running a command """

    @wraps(f)
    def wrapped(self, *args, **kwargs):
        if not self.warmed_up:
            self.warmup()
        return f(self, *args, **kwargs)
    return wrapped

def warmup(f):
    """ Decorator to run warmup before running a command """
    def run(*args, **kwargs):
        from warmup import warmup
        warmup()
        return f(*args, **kwargs)
    return run

def annotate(self, text, annotators=None):
        """Return an AnnotatedDocument from the CoreNLP server.

        :param (str) text: text to be annotated
        :param (list[str]) annotators: a list of annotator names

        See a list of valid annotator names here:
          http://stanfordnlp.github.io/CoreNLP/annotators.html

        :return (AnnotatedDocument): an annotated document
        """
        if not self.server:
            raise ValueError("Server not started.")
        params = {'text': text, 'properties': self.properties}
        if annotators is not None:
            params['annotators'] = ','.join(annotators)
        r = requests.post(self.url, data=params)
        if r.status_code != 200:
            raise ValueError('Unexpected response: %s' % r.text)
        return AnnotatedDocument(r.text)

