def decode_unicode_string(string):
    """
    Decode string encoded by `unicode_string`
    """
    if string.startswith('[BASE64-DATA]') and string.endswith('[/BASE64-DATA]'):
        return base64.b64decode(string[len('[BASE64-DATA]'):-len('[/BASE64-DATA]')])
    return string

def decode_unicode_string(string):
    """
    Decode string encoded by `unicode_string`
    """
    return string.encode("utf-8").decode("unicode_escape")

def _get_value_from_json(self, dict_path, metrics_json):
        """
        Get a value from a dictionary under N keys, represented as str("key1.key2...key{n}")
        """
        for key in dict_path.split('.'):
            if key in metrics_json:
                metrics_json = metrics_json.get(key)
            else:
                return None
        return metrics_json

def _get_value_from_json(self, dict_path, metrics_json):
        """
        Get a value from a dictionary under N keys, represented as str("key1.key2...key{n}")
        """
        if not isinstance(dict_path, str):
            raise Exception("dict_path should be of type str")
        if not dict_path.startswith("."):
            raise Exception("dict_path should start with a dot")
        if dict_path == ".":
            return metrics_json
        keys = dict_path.split(".")
        for key in keys:
            if not isinstance(metrics_json, dict):
                raise Exception("Dict path %s doesn't exist in metrics_json" % (dict_path))
            metrics_json = metrics_json[key]
        return metrics_json

def process_md5(md5_output, pattern=r"=\s+(\S+)"):
        """
        Process the string to retrieve the MD5 hash

        Output from Cisco IOS (ASA is similar)
        .MD5 of flash:file_name Done!
        verify /md5 (flash:file_name) = 410db2a7015eaa42b1fe71f1bf3d59a2
        """
        match = re.search(pattern, md5_output)
        if match:
            return match.group(1)
        else:
            raise ValueError("Invalid output from MD5 command: {}".format(md5_output))

def process_md5(md5_output, pattern=r"=\s+(\S+)"):
        """
        Process the string to retrieve the MD5 hash

        Output from Cisco IOS (ASA is similar)
        .MD5 of flash:file_name Done!
        verify /md5 (flash:file_name) = 410db2a7015eaa42b1fe71f1bf3d59a2
        """
        match = re.search(pattern, md5_output, re.M)
        if match:
            return match.group(1)
        else:
            return None

def del_ns(self, namespace):
        """ will remove a namespace ref from the manager. either Arg is
        optional.

        args:
            namespace: prefix, string or Namespace() to remove
        """
        if isinstance(namespace, Namespace):
            namespace = namespace.prefix
        if namespace is None:
            self._namespaces = {}
        else:
            namespace = namespace.lower()
            if namespace in self._namespaces:
                del self._namespaces[namespace]

