def max(self):
        """Maximum, ignorning nans."""
        if "max" not in self.attrs.keys():

            def f(dataset, s):
                return np.nanmax(dataset[s])

            self.attrs["max"] = np.nanmax(list(self.chunkwise(f).values()))
        return self.attrs["max"]

def max(self):
        """Maximum, ignorning nans."""
        return max(x for x in self.items() if not math.isnan(x))

def post(self, request, *args, **kwargs):
        """ Triggers the task that sends invitation messages
        """
        status = 201
        accepted = {"accepted": True}
        send_invite_messages.apply_async()
        return Response(accepted, status=status)

def post(self, request, *args, **kwargs):
        """ Triggers the task that sends invitation messages
        """
        if request.user.is_authenticated:
            try:
                invitation = Invitation.objects.get(
                    pk=kwargs.get('invitation_id')
                )
                if invitation.status == Invitation.SENT:
                    invitation.status = Invitation.PROCESSING
                    invitation.save()
                    send_invitation.delay(
                        invitation.pk,
                        request.user.pk,
                        request.META.get('HTTP_USER_AGENT')
                    )
                    return Response(
                        {'status': 'ok'},
                        status=status.HTTP_200_OK
                    )
                else:
                    return Response(
                        {'status': 'fail'},
                        status=status.HTTP_400_BAD_REQUEST
                    )
            except Invitation.DoesNotExist:
                return Response(
                    {'status': 'fail'},
                    status=status.HTTP_404_NOT_FOUND
                )
        else:
            return Response(
                {'status': 'fail'},
                status=status.HTTP_401_UNAUTHORIZED
            )

def load(cls, keys):
        """
        Load a set of conversations by their keys.
        """
        conversations = []
        for key in keys:
            conversation = unitdata.kv().get(key)
            if conversation:
                conversations.append(cls.deserialize(conversation))
        return conversations

