def xhtml_escape(value: Union[str, bytes]) -> str:
    """Escapes a string so it is valid within HTML or XML.

    Escapes the characters ``<``, ``>``, ``"``, ``'``, and ``&``.
    When used in attribute values the escaped strings must be enclosed
    in quotes.

    .. versionchanged:: 3.2

       Added the single quote to the list of escaped characters.
    """
    if isinstance(value, str):
        return _xhtml_escape_utf8(value)
    else:
        return _xhtml_escape_bytes(value)

def _validate_schema(self):
        """
        Validates provider schema for syntax issues. Raises :class:`~notifiers.exceptions.SchemaError` if relevant

        :raises: :class:`~notifiers.exceptions.SchemaError`
        """
        try:
            log.debug("validating provider schema")
            self.validator.check_schema(self.schema)
        except jsonschema.SchemaError as e:
            raise SchemaError(
                schema_error=e.message, provider=self.name, data=self.schema
            )

def _validate_schema(self):
        """
        Validates provider schema for syntax issues. Raises :class:`~notifiers.exceptions.SchemaError` if relevant

        :raises: :class:`~notifiers.exceptions.SchemaError`
        """

        schema = self.get_schema()

        if not schema:
            raise SchemaError(
                "Schema is not defined for provider {provider}".format(
                    provider=self.provider_name
                )
            )

        try:
            jsonschema.validate(instance=self.data, schema=schema)
        except jsonschema.ValidationError as e:
            raise SchemaError(
                "Schema validation error for provider {provider}: {error}".format(
                    provider=self.provider_name, error=e.message
                )
            )

def find_parameter(parameters, **kwargs):
    """
    Given a list of parameters, find the one with the given name.
    """
    matching_parameters = filter_parameters(parameters, **kwargs)
    if len(matching_parameters) == 1:
        return matching_parameters[0]
    elif len(matching_parameters) > 1:
        raise MultipleParametersFound()
    raise NoParameterFound()

def find_parameter(parameters, **kwargs):
    """
    Given a list of parameters, find the one with the given name.
    """
    for p in parameters:
        if p.name == kwargs.get("name"):
            return p

def clean_upload(self, query='/content/uploads/'):
        """
        pulp leaves droppings if you don't specifically tell it
        to clean up after itself. use this to do so.
