def add_or_update(self, app_id, value):
        """
        Adding or updating the evalution.
        :param app_id:  the ID of the post.
        :param value: the evaluation
        :return:  in JSON format.
        """
        MEvaluation.add_or_update(self.userinfo.uid, app_id, value)

        out_dic = {
            'eval0': MEvaluation.app_evaluation_count(app_id, 0),
            'eval1': MEvaluation.app_evaluation_count(app_id, 1)
        }

        return json.dump(out_dic, self)

def add_or_update(self, app_id, value):
        """
        Adding or updating the evalution.
        :param app_id:  the ID of the post.
        :param value: the evaluation
        :return:  in JSON format.
        """
        if not self.is_valid_id(app_id):
            return self.error_response('invalid app id')
        if not self.is_valid_value(value):
            return self.error_response('invalid value')
        app = self.get_app(app_id)
        if not app:
            return self.error_response('invalid app id')
        if not self.is_valid_user_id(app['user_id']):
            return self.error_response('invalid user id')
        if not self.is_valid_app_id(app_id):
            return self.error_response('invalid app id')
        if not self.is_valid_app_id(app['user_id']):
            return self.error_response('invalid user id')
        if app['status'] != 1:
            return self.error_response('invalid app status')
        if not self.is_valid_value(value):
            return self.error_response('invalid value')
        result = self.get_evaluation(app_id)
        if result:
            self.update_evaluation(app_id, value)
        else:
            self.add_evaluation(app_id, value)
        return self.success_response('success')

def _loop_payload(params):
    """
    Pass in a dictionary of parameters, loop through them and build a payload containing,
    parameters who's values are not None.
    """

    #construct the payload
