def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    backup_base = '/var/local/woven-backup'
    backup_path = ''.join([backup_base,path])
    if exists(backup_path):
        if delete_backup:
            sudo('mv -f %s %s'% (backup_path,path))
        else:
            sudo('cp -f %s %s'% (backup_path,path))

def _restore_file(path, delete_backup=True):
    """
    Restore a file if it exists and remove the backup
    """
    if not os.path.isfile(path):
        return
    if os.path.isfile(path + '.bak'):
        shutil.copy(path + '.bak', path)
        if delete_backup:
            os.remove(path + '.bak')

def local_rfcformat(dt):
    """Return the RFC822-formatted representation of a timezone-aware datetime
    with the UTC offset.
    """
    # Workaround for Python 2.6
    if hasattr(dt, 'utcoffset'):
        offset = dt.utcoffset()
    else:
        offset = dt.tzinfo.utcoffset(dt)

    if offset is None:
        return dt.strftime('%a, %d %b %Y %H:%M:%S')
    else:
        sign = '-' if offset < timedelta(0) else '+'
        offset = offset.seconds + offset.days * 86400
        offset = offset / 60
        hours = offset / 60
        minutes = offset % 60
        return dt.strftime('%a, %d %b %Y %H:%M:%S %z')

def parse(self, parser):
        """Main method to render data into the template."""
        lineno = next(parser.stream).lineno

        if parser.stream.skip_if('name:short'):
            parser.stream.skip(1)
            short = parser.parse_expression()
        else:
            short = nodes.Const(False)

        result = self.call_method('_commit_hash', [short], [], lineno=lineno)
        return nodes.Output([result], lineno=lineno)

def _read_line(self, f):
        """
        Reads one non empty line (if it's a comment, it skips it).
        """
        line = f.readline().strip()
        while line.startswith('#') and len(line.strip()) > 0:
            line = f.readline().strip()
        if len(line) == 0:
            raise ValueError('No data in file')
        return line

def write_to_file(self, destination_path):
        """
        Writes the metadata json or xml to a file.

        :param destination_path: the file path the file format is inferred
        from the destination_path extension.
        :type destination_path: str
        :return: the written metadata
        :rtype: str
        """
        if destination_path.endswith('.json'):
            return self._write_json(destination_path)
        elif destination_path.endswith('.xml'):
            return self._write_xml(destination_path)
        else:
            raise ValueError('Unsupported file type. Expected either .json or .xml extension.')

def get_unpatched_class(cls):
    """Protect against re-patching the distutils if reloaded

    Also ensures that no other distutils extension monkeypatched the distutils
    first.
    """
    external_bases = (
        cls
        for cls in _get_mro(cls)
        if not cls.__module__.startswith('setuptools')
    )
    base = next(external_bases)
    if not base.__module__.startswith('distutils'):
        msg = "distutils has already been patched by %r" % cls
        raise AssertionError(msg)
    return base

