def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    try:
        return ~x.isin(y)
    except AttributeError:
        if is_list_like(x):
            try:
                return ~y.isin(x)
            except AttributeError:
                pass
        return x not in y

def _not_in(x, y):
    """Compute the vectorized membership of ``x not in y`` if possible,
    otherwise use Python.
    """
    # If we can broadcast, then use that.
    try:
        broadcast_x = np.broadcast_to(x, y.shape)
    except ValueError:
        broadcast_x = None
    if broadcast_x is not None:
        return np.logical_not(broadcast_x.reshape(y.shape) == y)

    # If we can use fancy indexing, then use that.
    try:
        index = np.broadcast_to(np.arange(y.shape[0]), x.shape)
    except ValueError:
        index = None
    if index is not None:
        return np.logical_not(np.in1d(x, y, assume_unique=True, invert=True))

    # Otherwise, just use Python.
    return np.array([i not in y for i in x])

def from_param(cls, param):
        """
        Construct a CommandSpec from a parameter to build_scripts, which may
        be None.
        """
        if isinstance(param, cls):
            return param
        if isinstance(param, list):
            return cls(param)
        if param is None:
            return cls.from_environment()
        # otherwise, assume it's a string.
        return cls.from_string(param)

def from_param(cls, param):
        """
        Construct a CommandSpec from a parameter to build_scripts, which may
        be None.
        """
        if param is None:
            return cls()
        elif isinstance(param, dict):
            return cls.from_dict(param)
        elif isinstance(param, cls):
            return param
        else:
            raise TypeError(
                "Expected a CommandSpec or None, but got a {}.".format(
                    type(param)))

def add_function(self, func):
        """ Record line profiling information for the given Python function.
        """
        try:
            # func_code does not exist in Python3
            code = func.__code__
        except AttributeError:
            import warnings
            warnings.warn("Could not extract a code object for the object %r"
                          % (func,))
            return
        if code not in self.code_map:
            self.code_map[code] = {}
            self.functions.append(func)

def add_function(self, func):
        """ Record line profiling information for the given Python function.
        """
        if not callable(func):
            raise TypeError('Expected callable, got %r' % func)
        if func not in self._functions:
            self._functions.append(func)
            self._line_info[func] = {}
            self._line_counts[func] = 0
        self._line_counts[func] += 1

def coerce_value(cls, v):
        """Coerce a value to the right type for the collection, or return it if
        it is already of the right type."""
        if isinstance(v, cls.itemtype):
            return v
        else:
            try:
                return cls.coerceitem(v)
            except Exception as e:
                raise exc.CollectionItemCoerceError(
                    itemtype=cls.itemtype,
                    colltype=cls,
                    passed=v,
                    exc=e,
                )

def coerce_value(cls, v):
        """Coerce a value to the right type for the collection, or return it if
        it is already of the right type."""
        if not isinstance(v, cls):
            return cls(v)
        return v

