def correct(word, known_words):
    """
    :param word: Word to correct
    :type word: string
    :param known_words: List of known words
    :type known_words: iterable of strings

    Given **word**, suggests a correction from **known_words**. If no reasonably close correction is found, returns
    **word**.
    """
    if word in known_words:
        return word

    # Check for words with the same length and the same first letter
    if len(word) >= 3:
        first_letter = word[0]
        for candidate in known_words:
            if candidate.startswith(first_letter) and candidate != word:
                if levenshtein_distance(word, candidate) < 2:
                    return candidate

    # Check for words with the same length
    for candidate in known_words:
        if len(candidate) == len(word) and candidate != word:
            if levenshtein_distance(word, candidate) < 2:
                return candidate

    # Check for words with the same length and the same last letter
    last_letter = word[-1]
    for candidate in known_words:
        if candidate.endswith(last_letter) and candidate != word:
            if levenshtein_distance(word, candidate) < 2:
                return candidate

    # Check for words with the same length and the same middle letter
    middle_letter = word[len(word) // 2]
    for candidate in known_words:
        if candidate.count(middle_letter) == 1 and candidate != word:
            if levenshtein_distance(word, candidate) < 2:
                return candidate

    return word

def format(self, response):
        """ Format the data.

        In derived classes, it is usually better idea to override
        ``_format_data()`` than this method.

        :param response: devil's ``Response`` object or the data
                         itself. May also be ``None``.
        :return: django's ``HttpResponse``

        todo: this shouldn't change the given response. only return the
        formatted response.
        """
        if response is None:
            return HttpResponse(content=self.content)
        elif isinstance(response, Response):
            return HttpResponse(content=self._format_data(response))
        else:
            return HttpResponse(content=response)

def stringpatterncounter(table, field):
    """
    Profile string patterns in the given field, returning a :class:`dict`
    mapping patterns to counts.

    """
    pattern_counts = {}
    for value in table.column(field):
        if isinstance(value, six.string_types):
            for pattern in stringpatterns(value):
                if pattern not in pattern_counts:
                    pattern_counts[pattern] = 0
                pattern_counts[pattern] += 1
    return pattern_counts

