def _get_debug_formatter(conf):
    """Get debug formatter based on configuration.

    :param conf: configurtration namespace (ex. argparser)

    --debug: log line numbers, file data
    --verbose: standard log format at a DEBUG loglevel
    --quiet: turn down logging output (logging.WARNING)
    default is logging.INFO
    """
    if conf.debug is True:
        return DebugFormatter('%(pathname)s:%(lineno)d: %(levelname)-8s '
                              '%(message)s')
    elif conf.verbose is True:
        return logging.Formatter(
            '%(name)-30s: %(levelname)-8s %(message)s')
    elif conf.quiet is True:
        return logging.Formatter('%(message)s')
    else:
        return logging.Formatter(logging.BASIC_FORMAT)

def _get_debug_formatter(conf):
    """Get debug formatter based on configuration.

    :param conf: configurtration namespace (ex. argparser)

    --debug: log line numbers, file data
    --verbose: standard log format at a DEBUG loglevel
    --quiet: turn down logging output (logging.WARNING)
    default is logging.INFO
    """
    if conf.debug:
        return logging.Formatter(
            '%(asctime)s %(levelname)s %(filename)s:%(lineno)d %(message)s')
    elif conf.verbose:
        return logging.Formatter(
            '%(asctime)s %(levelname)s %(message)s')
    elif conf.quiet:
        return logging.Formatter(
            '%(levelname)s %(message)s')
    else:
        return logging.Formatter(
            '%(asctime)s %(levelname)s %(message)s')

def setDaemon(self, runnable, isdaemon, noregister = False):
        """
        If a runnable is a daemon, it will not keep the main loop running. The main loop will end when all alived runnables are daemons.
        """
        if not noregister and runnable not in self.registerIndex:
            self.register((), runnable)
        if isdaemon:
            self.daemons.add(runnable)
        else:
            self.daemons.discard(runnable)

def _createStatsDict(self, headers, rows):
        """Utility method that returns database stats as a nested dictionary.

        @param headers: List of columns in query result.
        @param rows:    List of rows in query result.
        @return:        Nested dictionary of values.
                        First key is the database name and the second key is the 
                        statistics counter name. 

        """
        dbstats = {}
        for row in rows:
            dbstats[row[0]] = dict(zip(headers[1:], row[1:]))
        return dbstats

def _createStatsDict(self, headers, rows):
        """Utility method that returns database stats as a nested dictionary.

        @param headers: List of columns in query result.
        @param rows:    List of rows in query result.
        @return:        Nested dictionary of values.
                        First key is the database name and the second key is the 
                        statistics counter name. 

        """
        statsDict = {}
        for row in rows:
            dbName = row[0]
            if dbName not in statsDict:
                statsDict[dbName] = {}
            statsDict[dbName][row[1]] = row[2]
        return statsDict

def get(self, name=None):
        """Get initial yield value, or result of send(name) if name given."""
        if name is None:
            return self.init_value
        elif not self.support_name:
            msg = "generator does not support get-by-name: function {!r}"
            raise TypeError(msg.format(self.function))
        try:
            value = self.generator.send(name)
        except StopIteration:
            msg = "generator didn't yield: function {!r}"
            raise RuntimeError(msg.format(self.function))
        return value

def get(self, name=None):
        """Get initial yield value, or result of send(name) if name given."""
        if name is None:
            return self.yield_value
        else:
            return self.yield_value.send(name)

def iter_range(reader, start, end, prev_size=0):
    """
    Creates an iterator which iterates over lines where
    start <= line < end (end exclusive)
    """
    if end <= start:
        return
    if start == end:
        yield start
        return
    if start < end:
        yield start
        start += 1
    for line in reader:
        if line.startswith(start):
            if line.startswith(end):
                return
            yield line
        elif line.startswith(end):
            return
        elif line.startswith(start):
            yield line
        else:
            if prev_size:
                yield line[prev_size:]

def is_valid_pid_to_be_updated(did):
    """Assert that ``did`` is the PID of an object that can be updated (obsoleted) with
    MNStorage.update()"""
    if not d1_gmn.app.did.is_valid_pid_to_be_updated(did):
        raise d1_common.types.exceptions.InvalidRequest(
            0,
            'Object cannot be updated because the identifier for the object to be '
