def is_valid_pid_to_be_updated(did):
    """Assert that ``did`` is the PID of an object that can be updated (obsoleted) with
    MNStorage.update()"""
    from .models import (
        Document,
        Folder,
        Group,
        Item,
        License,
        Location,
        Person,
        Project,
        Subject,
    )

    if isinstance(did, Document):
        return True
    if isinstance(did, Folder):
        return True
    if isinstance(did, Group):
        return True
    if isinstance(did, Item):
        return True
    if isinstance(did, License):
        return True
    if isinstance(did, Location):
        return True
    if isinstance(did, Person):
        return True
    if isinstance(did, Project):
        return True
    if isinstance(did, Subject):
        return True

    return False

def moving_average(data, periods, type='simple'):
    """
    compute a <periods> period moving average.
    type is 'simple' | 'exponential'
    """
    if type == 'simple':
        return pd.Series(data).rolling(periods).mean().values
    elif type == 'exponential':
        return pd.Series(data).ewm(span=periods).mean().values
    else:
        raise ValueError('Unknown type')

def parse_ast(source, filename=None):
    """Parse source into a Python AST, taking care of encoding."""
    if isinstance(source, text_type) and sys.version_info[0] == 2:
        # ast.parse() on Python 2 doesn't like encoding declarations
        # in Unicode strings
        source = CODING_COOKIE_RE.sub(r'\1', source, 1)
    return ast.parse(source, filename or '<unknown>')

def parse_ast(source, filename=None):
    """Parse source into a Python AST, taking care of encoding."""
    if filename and not PY3:
        # Work around http://bugs.python.org/issue10962
        with open(filename, 'rb') as fp:
            encoding = tokenize.detect_encoding(fp.readline)[0]
        source = source.decode(encoding)
    try:
        return ast.parse(source, filename=filename)
    except SyntaxError:
        if filename:
            # Insert a hint about the filename
            raise
        raise

def send_event(self, name, ev, state=None):
        """
        Send the specified event to the RyuApp instance specified by name.
        """

        if name in SERVICE_BRICKS:
            if isinstance(ev, EventRequestBase):
                ev.src = self.name
            LOG.debug("EVENT %s->%s %s",
                      self.name, name, ev.__class__.__name__)
            SERVICE_BRICKS[name]._send_event(ev, state)
        else:
            LOG.debug("EVENT LOST %s->%s %s",
                      self.name, name, ev.__class__.__name__)

def send_event(self, name, ev, state=None):
        """
        Send the specified event to the RyuApp instance specified by name.
        """
        if state is None:
            state = self.name

        ryu_app = self._ryu_app_instances.get(state)
        if ryu_app is None:
            raise ValueError('Unknown state: {}'.format(state))
        ryu_app.send_event(ev)

