def to_creator(self, subject, desc):
        """ Return a python-zimbra dict for CreateTaskRequest

        Example :
        <CreateTaskRequest>
            <m su="Task subject">
                <inv>
                    <comp name="Task subject">
                        <fr>Task comment</fr>
                        <desc>Task comment</desc>
                    </comp>
                </inv>
                <mp>
                    <content/>
                </mp>
            </m>
        </CreateTaskRequest>
        """

        task = {
            'm': {
                'su': subject,
                'inv': {
                    'comp': {
                        'name': subject,
                        'fr': {'_content': desc},
                        'desc': {'_content': desc},
                        'percentComplete': '0'
                    }
                },
                'mp': {
                    'content': {}
                }
            }
        }

        return task

def to_creator(self, subject, desc):
        """ Return a python-zimbra dict for CreateTaskRequest

        Example :
        <CreateTaskRequest>
            <m su="Task subject">
                <inv>
                    <comp name="Task subject">
                        <fr>Task comment</fr>
                        <desc>Task comment</desc>
                    </comp>
                </inv>
                <mp>
                    <content/>
                </mp>
            </m>
        </CreateTaskRequest>
        """
        # subject = self.sanitize(subject)
        # desc = self.sanitize(desc)
        task = {
            'm': {
                'su': subject,
                'inv': {
                    'comp': {
                        'name': subject,
                        'desc': desc,
                        'fr': desc,
                    }
                },
                'mp': {
                    'content': ''
                }
            }
        }
        return task

def get_hdrgos_g_usrgos(self, usrgos):
        """Return hdrgos which contain the usrgos."""
        hdrgos_for_usrgos = set()
        hdrgos_all = self.get_hdrgos()
        usrgo2hdrgo = self.get_usrgo2hdrgo()
        for usrgo in usrgos:
            if usrgo in hdrgos_all:
                hdrgos_for_usrgos.add(usrgo)
                continue
            hdrgo_cur = usrgo2hdrgo.get(usrgo, None)
            if hdrgo_cur is not None:
                hdrgos_for_usrgos.add(hdrgo_cur)
        return hdrgos_for_usrgos

def get_hdrgos_g_usrgos(self, usrgos):
        """Return hdrgos which contain the usrgos."""
        if usrgos is None:
            return None

        hdrgos = []
        for usrgo in usrgos:
            hdrgos.append(self.get_hdrgo(usrgo))

        return hdrgos

def to_str(instance, encoding='utf-8'):
    """Convert an instance recursively to string."""
    if isinstance(instance, str):
        return instance
    elif hasattr(instance, 'decode'):
        return instance.decode(encoding)
    elif isinstance(instance, list):
        return list([to_str(item, encoding) for item in instance])
    elif isinstance(instance, tuple):
        return tuple([to_str(item, encoding) for item in instance])
    elif isinstance(instance, dict):
        return dict(
            [(to_str(key, encoding), to_str(value, encoding))
                for key, value in instance.items()])
    else:
        return instance

def to_str(instance, encoding='utf-8'):
    """Convert an instance recursively to string."""
    if isinstance(instance, str):
        return instance
    if isinstance(instance, bytes):
        return instance.decode(encoding)
    if isinstance(instance, (list, tuple)):
        return type(instance)(to_str(x, encoding) for x in instance)
    if isinstance(instance, dict):
        return type(instance)((to_str(k, encoding), to_str(v, encoding))
                              for k, v in instance.items())
    return str(instance)

def mouseReleaseEvent(self, event):
        """
        Reimplements the :meth:`QLabel.mouseReleaseEvent` method.

        :param event: QEvent.
        :type event: QEvent
        """

        if self.underMouse():
            if self.__checkable:
                self.set_checked(not self.__checked)
            else:
                self.setPixmap(self.__active_pixmap)
        else:
            self.setPixmap(self.__default_pixmap)
        self.released.emit()
        self.clicked.emit()

def get_for_update(self, connection_name='DEFAULT', **kwargs):

        """
        http://docs.sqlalchemy.org/en/latest/orm/query.html?highlight=update#sqlalchemy.orm.query.Query.with_for_update  # noqa
        """

        return self.filter_by(**kwargs).with_for_update(
            of=self._class_name,
            read=True,
            nowait=False,
            connection_name=connection_name
        )

def get_request_token(self, request):
        """
           request the token to the external service
        """
        params = {
            'oauth_callback': request.build_absolute_uri(
                reverse('oauth_callback')
            ),
        }
        url = self.get_request_token_url()
        return self.request_token(url, params)

def parse_schema_definition(lexer: Lexer) -> SchemaDefinitionNode:
    """SchemaDefinition"""
    start = lexer.token
    expect_keyword(lexer, "schema")
    directives = parse_directives(lexer, True)
    operation_types = many_nodes(
        lexer, TokenKind.BRACE_L, parse_operation_type_definition, TokenKind.BRACE_R
    )
    return SchemaDefinitionNode(
        directives=directives, operation_types=operation_types, loc=loc(lexer, start)
    )

def timemeter(msg=None):
    """Timer meter

        Use this annotation method can calculate the execute time.
    :param msg: custom message output
    :return: fn values
    """
    def _time_meter(fn):
        @functools.wraps(fn)
        def _wrapper(*args, **kwargs):
            mark = timeit.default_timer()
            result = fn(*args, **kwargs)
            cost = timeit.default_timer() - mark
            if msg:
                logger.info(msg, cost)
            else:
                logger.info('Execute <%s.%s> method cost %s seconds.', fn.__module__, fn.__name__, cost)
            return result
        return _wrapper
    return _time_meter

def create_files(filedef, cleanup=True):
    """Contextmanager that creates a directory structure from a yaml
       descripttion.
    """

    def _create_files(directory):
        for f in filedef:
            if f.startswith(".."):
                # skip parent directory
                continue
            if f.endswith("/"):
                # create a directory
                path = os.path.join(directory, f[:-1])
                os.mkdir(path)
            else:
                # create a file
                path = os.path.join(directory, f)
                with open(path, "w") as fd:
                    fd.write("")

    with tempfile.TemporaryDirectory() as tmpdir:
        _create_files(tmpdir)
        yield tmpdir
        if cleanup:
            shutil.rmtree(tmpdir)

def _update_dict(self, to_dict, from_dict):
        """ Recursively merges the fields for two dictionaries.

        Args:
            to_dict (dict): The dictionary onto which the merge is executed.
            from_dict (dict): The dictionary merged into to_dict
        """
        for key in from_dict:
            if key in to_dict:
                if isinstance(to_dict[key], dict) and isinstance(from_dict[key], dict):
                    self._update_dict(to_dict[key], from_dict[key])
                elif to_dict[key] == from_dict[key]:
                    pass  # same leaf value
                else:
                    to_dict[key] = from_dict[key]
            else:
                to_dict[key] = from_dict[key]

def __store_config(self, args, kwargs):
        """ Assign args to kwargs and store configuration. """
        signature = (
            'schema',
            'ignore_none_values',
            'allow_unknown',
            'require_all',
            'purge_unknown',
            'purge_readonly',
        )
        for i, p in enumerate(signature[: len(args)]):
            if p in kwargs:
                raise TypeError("__init__ got multiple values for argument " "'%s'" % p)
            else:
                kwargs[p] = args[i]
        self._config = kwargs

def __store_config(self, args, kwargs):
        """ Assign args to kwargs and store configuration. """
        # Assign args to kwargs
        for arg in args:
            if arg in kwargs:
                raise ValueError(f"Argument {arg} passed to __store_config already exists in kwargs.")
            kwargs[arg] = getattr(self, arg)
        # Store configuration
        self.kwargs = kwargs
        # Remove args from __init__
        for arg in args:
            setattr(self, arg, None)

def configure(root_url, **kwargs):
    """"
    Notice that `configure` can either apply to the default configuration or
    `Client.config`, which is the  configuration used by the current thread
    since `Client` inherits form `threading.local`.
    """
    default = kwargs.pop('default', True)
    kwargs['client_agent'] = 'example-client/' + __version__
    if 'headers' not in kwargs:
        kwargs['headers'] = {}
    kwargs['headers']['Accept-Type'] = 'application/json'
    if default:
        default_config.reset(root_url, **kwargs)
    else:
        Client.config = wac.Config(root_url, **kwargs)

def configure(root_url, **kwargs):
    """"
    Notice that `configure` can either apply to the default configuration or
    `Client.config`, which is the  configuration used by the current thread
    since `Client` inherits form `threading.local`.
    """
    if root_url:
        kwargs['root_url'] = root_url

    def _apply(config):
        for k, v in kwargs.items():
            setattr(config, k, v)
    return _apply

def _has_example(self, label):
        """Whether this data type has an example with the given ``label``."""
        if label in self._raw_examples:
            return True
        else:
            for field in self.all_fields:
                dt, _ = unwrap_nullable(field.data_type)
                if not is_user_defined_type(dt) and not is_void_type(dt):
                    continue
                if label == field.name:
                    return True
            else:
                return False

def _has_example(self, label):
        """Whether this data type has an example with the given ``label``."""
        return label in self.examples

def parse_ini_file(self, path):
        """Parse ini file at ``path`` and return dict."""
        cfgobj = ConfigObj(path, list_values=False)

        def extract_section(namespace, d):
            cfg = {}
            for key, val in d.items():
                if isinstance(d[key], dict):
                    cfg.update(extract_section(namespace + [key], d[key]))
                else:
                    cfg['_'.join(namespace + [key]).upper()] = val

            return cfg

        return extract_section([], cfgobj.dict())

def parse_ini_file(self, path):
        """Parse ini file at ``path`` and return dict."""
        with open(path, "r") as f:
            return parse_ini(f)

def symmetric_difference_update(self, that):
        """
        Update the set, keeping only elements found in either *self* or *that*,
        but not in both.
        """
        if not isinstance(that, Set):
            raise TypeError("can only symmetric_difference_update from another set")
        if self is that:
            self._check_for_inplace_mutation()
        for elem in that:
            if elem in self:
                self.remove(elem)
            else:
                self.add(elem)

def _merge_fix(d):
    """Fixes keys that start with "&" and "-"
        d = {
          "&steve": 10,
          "-gary": 4
        }
        result = {
          "steve": 10,
          "gary": 4
        }
    """
    if type(d) is dict:
        for key in d.keys():
            if key[0] in ('&', '-'):
                d[key[1:]] = _merge_fix(d.pop(key))
    return d

def _merge_fix(d):
    """Fixes keys that start with "&" and "-"
        d = {
          "&steve": 10,
          "-gary": 4
        }
        result = {
          "steve": 10,
          "gary": 4
        }
    """
    if not isinstance(d, dict):
        return d

    d = dict(d)
    for key, value in d.items():
        if key.startswith("&") or key.startswith("-"):
            new_key = key[1:]
            d[new_key] = value
            del d[key]

    return d

def build_image_from_inherited_image(self, image_name: str, image_tag: str,
                                         repo_path: Path,
                                         requirements_option: RequirementsOptions):
        """
        Builds a image with installed requirements from the inherited image. (Or just tags the image
        if there are no requirements.)

        See :meth:`build_image` for parameters descriptions.

        :rtype: docker.models.images.Image
        """
        if not self.is_image_built(image_name):
            raise ValueError(f"Image '{image_name}' is not built. Use `build_image` to build it.")

        if requirements_option.requirements_files_list:
            requirements_option.requirements_files_list.append(f"{repo_path}/requirements.txt")

            requirements_option.pip_options.append(f"--find-links={repo_path}/wheels")
            requirements_option.pip_options.append("--no-index")

        return self.build_image(image_name, image_tag, repo_path, requirements_option)

def clear(self, pat=None):
        """
        Minor diversion with built-in dict here;  clear can take a glob
        style expression and remove keys based on that expression.
        """
        if pat is None:
            return self.__dict__.clear()

        expr = re.compile(fnmatch.translate(pat))
        for key in tuple(self.keys()):
            #make sure the key is a str first
            if isinstance(key, string_types):
                if expr.match(key):
                    del self.__dict__[key]

def clear(self, pat=None):
        """
        Minor diversion with built-in dict here;  clear can take a glob
        style expression and remove keys based on that expression.
        """
        if pat is None:
            self.data = {}
        else:
            pat = re.compile(pat)
            self.data = dict([(k, v) for k, v in self.data.items() if not pat.match(k)])

def _get_formatted_val(self, obj, name, column):
        """
        Format the value of the attribute 'name' from the given object
        """
        attr_path = name.split('.')
        val = None
        tmp_val = obj
        for attr in attr_path:
            tmp_val = getattr(tmp_val, attr, None)
            if tmp_val is None:
                break
        if tmp_val is not None:
            val = tmp_val

        return format_value(column, val, self.config_key)

def _get_formatted_val(self, obj, name, column):
        """
        Format the value of the attribute 'name' from the given object
        """
        if column.get('formatter'):
            return column['formatter'](obj, name)
        else:
            return getattr(obj, name)

