def _parse_java_version(line: str) -> tuple:
    """ Return the version number found in the first line of `java -version`

    >>> _parse_java_version('openjdk version "11.0.2" 2018-10-16')
    (11, 0, 2)
    """
    m = VERSION_RE.search(line)
    version_str = m and m.group(0).replace('"', '') or '0.0.0'
    if '_' in version_str:
        fst, snd = version_str.split('_', maxsplit=2)
        version = parse_version(fst)
        return (version[1], version[2], int(snd))
    else:
        return parse_version(version_str)

def _parse_java_version(line: str) -> tuple:
    """ Return the version number found in the first line of `java -version`

    >>> _parse_java_version('openjdk version "11.0.2" 2018-10-16')
    (11, 0, 2)
    """
    m = re.search(r'openjdk version "([^"]+)"', line)
    if m:
        return tuple(int(x) for x in m.group(1).split('.'))
    return (0, 0, 0)

def _reorder(string, salt):
    """Reorders `string` according to `salt`."""
    result = []
    for c in string:
        result.append(salt[c])
    return ''.join(result)

def builds(self, confs):
        """For retro compatibility directly assigning builds"""
        self._named_builds = {}
        self._builds = []
        for values in confs:
            if len(values) == 2:
                self._builds.append(BuildConf(values[0], values[1], {}, {}, self.reference))
            elif len(values) == 4:
                self._builds.append(BuildConf(values[0], values[1], values[2], values[3],
                                              self.reference))
            elif len(values) != 5:
                raise Exception("Invalid build configuration, has to be a tuple of "
                                "(settings, options, env_vars, build_requires, reference)")
            else:
                self._builds.append(BuildConf(*values))

def from_dict(d):
    """
    load an nparray object from a dictionary

    @parameter str d: dictionary representing the nparray object
    """
    if isinstance(d, str):
        return from_json(d)

    if not isinstance(d, dict):
        raise TypeError("argument must be of type dict")
    if 'nparray' not in d.keys():
        raise ValueError("input dictionary missing 'nparray' entry")

    classname = d.pop('nparray').title()
    return getattr(_wrappers, classname)(**d)

def from_dict(d):
    """
    load an nparray object from a dictionary

    @parameter str d: dictionary representing the nparray object
    """
    return np.frombuffer(base64.b64decode(d['base64']), d['dtype']).reshape(d['shape'])

def parse_config_list(config_list):
  """
  Parse a list of configuration properties separated by '='
  """
  if config_list is None:
    return {}
  else:
    mapping = {}
    for pair in config_list:
      if (constants.CONFIG_SEPARATOR not in pair) or (pair.count(constants.CONFIG_SEPARATOR) != 1):
        raise ValueError("configs must be passed as two strings separted by a %s", constants.CONFIG_SEPARATOR)
      (config, value) = pair.split(constants.CONFIG_SEPARATOR)
      mapping[config] = value
    return mapping

def parse_config_list(config_list):
  """
  Parse a list of configuration properties separated by '='
  """
  configs = {}
  for config in config_list:
    key, value = config.split("=")
    configs[key] = value
  return configs

def _validI(x, y, weights):
    """
    return indices that have enough data points and are not erroneous 
    """
    return (x > 0) & (y > 0) & (x < 2*np.pi) & (y < 2*np.pi) & (weights > 0)

def __find_rows(self, find_url, **attributes):
        """
            :param find_url: URL of the find api
            :type find_url: string
            :return: The Response returned by requests including the list of documents based on find_url
            :rtype: Response object
        """
        req = self.url + find_url

        # Add range and sort parameters
        params = {
            "range": attributes.get("range", "all"),
            "sort": attributes.get("sort", [])
        }

        # Add body
        data = {
            "query": attributes.get("query", {})
        }

        try:
            return requests.post(req, params=params, json=data, proxies=self.proxies, auth=self.auth, verify=self.cert)
        except requests.exceptions.RequestException as e:
            raise TheHiveException("Error: {}".format(e))

def _temp_bool_prop(propname, doc="", default=False):
    """Creates a property that uses the :class:`_TempBool` class

    Parameters
    ----------
    propname: str
        The attribute name to use. The _TempBool instance will be stored in the
        ``'_' + propname`` attribute of the corresponding instance
    doc: str
        The documentation of the property
    default: bool
        The default value of the _TempBool class"""
    def getx(self):
        if getattr(self, '_' + propname, None) is not None:
            return getattr(self, '_' + propname)
        else:
            setattr(self, '_' + propname, _TempBool(default))
        return getattr(self, '_' + propname)

    def setx(self, value):
        getattr(self, propname).value = bool(value)

    def delx(self):
        getattr(self, propname).value = default

    return property(getx, setx, delx, doc)

def get_visible_items(self):
        """Return a list of all visible items in the treewidget."""
        items = []
        iterator = QTreeWidgetItemIterator(self)
        while iterator.value():
            item = iterator.value()
            if not item.isHidden():
                if item.parent():
                    if item.parent().isExpanded():
                        items.append(item)
                else:
                    items.append(item)
            iterator += 1
        return items

def get_visible_items(self):
        """Return a list of all visible items in the treewidget."""
        items = []
        for index in range(self.topLevelItemCount()):
            item = self.topLevelItem(index)
            if item.isVisible():
                items.append(item)
        return items

def GET_namespace_num_names(self, path_info, namespace_id):
        """
        Get the number of names in a namespace
        Reply the number on success
        Reply 404 if the namespace does not exist
        Reply 502 on failure to talk to the blockstack server
        """
        if not check_namespace(namespace_id):
            return self._reply_json({'error': 'Invalid namespace'}, status_code=400)

        blockstackd_url = get_blockstackd_url()
        name_count = blockstackd_client.get_num_names_in_namespace(namespace_id, hostport=blockstackd_url)
        if json_is_error(name_count):
            log.error("Failed to load namespace count for {}: {}".format(namespace_id, name_count['error']))
            return self._reply_json({'error': 'Failed to load namespace count: {}'.format(name_count['error'])}, status_code=404)

        self._reply_json({'names_count': name_count})

def GET_namespace_num_names(self, path_info, namespace_id):
        """
        Get the number of names in a namespace
        Reply the number on success
        Reply 404 if the namespace does not exist
        Reply 502 on failure to talk to the blockstack server
        """
        path = "/v1/namespaces/" + namespace_id + "/names"
        if path_info != path:
            return HTTPResponse(status=404)
        try:
            reply = self.fetch(self.blockstack_server + path)
            if reply.code == 200:
                return HTTPResponse(body=reply.body, status=reply.code,
                                    headers=reply.headers, request_version=reply.version,
                                    reason=reply.reason)
            else:
                return HTTPResponse(body=reply.body, status=reply.code,
                                    headers=reply.headers, request_version=reply.version,
                                    reason=reply.reason)
        except HTTPError as e:
            return HTTPResponse(body=e.read(), status=e.code,
                                headers=e.headers, request_version=e.version,
                                reason=e.reason)

def cmp(self,range2,overlap_size=0):
    """the comparitor for ranges

     * return 1 if greater than range2
     * return -1 if less than range2
     * return 0 if overlapped

    :param range2:
    :param overlap_size: allow some padding for an 'equal' comparison (default 0)
    :type range2: GenomicRange
    :type overlap_size: int

    """
    if self.start >= range2.start and self.end <= range2.end:
        return 0
    elif self.start >= range2.start:
        if self.end - self.start >= range2.end - range2.start + overlap_size:
            return 1
        else:
            return 0
    elif self.end <= range2.end:
        if range2.end - range2.start >= self.end - self.start + overlap_size:
            return -1
        else:
            return 0
    else:
        return -1

def get_pks_for_filter(self, key, filter_type, value):
        """Extract the pks from the zset key for the given type and value

        For the parameters, see BaseRangeIndex.get_pks_for_filter
        """
        if filter_type == 'gte':
            pks = self.zrangebyscore(key, value, 'inf')
        elif filter_type == 'lte':
            pks = self.zrangebyscore('-inf', value)
        elif filter_type == 'gt':
            pks = self.zrangebyscore(value, 'inf')
        elif filter_type == 'lt':
            pks = self.zrangebyscore('-inf', value)
        elif filter_type == 'eq':
            pks = [value]
        else:
            raise ValueError("Invalid filter type: %s" % filter_type)

        return pks

def _set_instance_ip(self):
        """
        Get the IP address based on instance ID.

        If public IP address not found attempt to get private IP.
        """
        try:
            ip_address = self.network.public_ip_addresses.get(
                self.running_instance_id, self.public_ip_name
            ).ip_address
        except Exception:
            try:
                ip_address = self.network.network_interfaces.get(
                    self.running_instance_id, self.nic_name
                ).ip_configurations[0].private_ip_address
            except Exception as error:
                raise AzureCloudException(
                    'Unable to retrieve instance IP address: {0}.'.format(
                        error
                    )
                )

        self.instance_ip = ip_address

def _set_instance_ip(self):
        """
        Get the IP address based on instance ID.

        If public IP address not found attempt to get private IP.
        """
        try:
            self._instance_ip = self._instance.public_ip_address
        except AttributeError:
            self._instance_ip = self._instance.private_ip_address
        if not self._instance_ip:
            raise AttributeError("No IP address found for instance {}".format(self._instance_id))

def geojson(self, feature_id):
        """GeoJSON representation of the marker as a point."""
        lat, lon = self.lat_lon
        return {
            'type': 'Feature',
            'id': feature_id,
            'geometry': {
                'type': 'Point',
                'coordinates': (lon, lat),
            },
        }

def geojson(self, feature_id):
        """GeoJSON representation of the marker as a point."""
        return {
            "type": "Feature",
            "geometry": {
                "type": "Point",
                "coordinates": self.coordinates,
            },
            "properties": {
                "title": self.title,
                "description": self.description,
                "feature_id": feature_id,
            },
        }

def resolve_service_spec(self, name, lineno):
        """Finds and links the ServiceSpec with the given name."""

        if name in self.service_specs:
            return self.service_specs[name].link(self)

        if '.' in name:
            include_name, component = name.split('.', 2)
            if include_name in self.included_scopes:
                return self.included_scopes[
                    include_name
                ].resolve_service_spec(component, lineno)

        raise ThriftCompilerError(
            'Unknown service "%s" referenced at line %d%s' % (
                name, lineno, self.__in_path()
            )
        )

def resolve_service_spec(self, name, lineno):
        """Finds and links the ServiceSpec with the given name."""
        if name not in self.specs:
            self.report(
                "service-spec-undefined",
                lineno,
                "service spec %r undefined" % name,
            )
            return None
        return self.specs[name]

def get_translation(self, lang, field):
        """
        Return the translation string of an specific field in a Translatable
        istance

        @type lang: string
        @param lang: a string with the name of the language

        @type field: string
        @param field: a string with the name that we try to get

        @rtype: string
        @return: Returns a translation string
        """
        # Read from cache
        key = self._get_translation_cache_key(lang, field)
        trans = cache.get(key, '')

        if not trans:
            trans_obj = self.get_translation_obj(lang, field)
            trans = getattr(trans_obj, 'translation', '')
            # if there's no translation text fall back to the model field
            if not trans:
                trans = getattr(self, field, '')
            # update cache
            cache.set(key, trans)
        return trans

def get_translation(self, lang, field):
        """
        Return the translation string of an specific field in a Translatable
        istance

        @type lang: string
        @param lang: a string with the name of the language

        @type field: string
        @param field: a string with the name that we try to get

        @rtype: string
        @return: Returns a translation string
        """
        lang = lang.lower()
        if lang in self.translations:
            if field in self.translations[lang]:
                return self.translations[lang][field]
            elif field in self.translations['default']:
                return self.translations['default'][field]
            else:
                return ""
        else:
            return ""

def _execute_callback(self, callback, data):
        """Execute the callback in another thread. Wait for and return the results."""
        web_client = WebClient(
            token=self.token, base_url=self.base_url, ssl=self.ssl, proxy=self.proxy
        )
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as executor:
            # Execute the callback on a separate thread,
            future = executor.submit(
                callback, rtm_client=self, web_client=web_client, data=data
            )

            while future.running():
                pass

            future.result()

def body_block_supplementary_material_render(supp_tags, base_url=None):
    """fig and media tag caption may have supplementary material"""
    source_data = []
    for supp_tag in supp_tags:
        for block_content in body_block_content_render(supp_tag, base_url=base_url):
            if block_content != {}:
                if "content" in block_content:
                    del block_content["content"]
                source_data.append(block_content)
    return source_data

def body_block_supplementary_material_render(supp_tags, base_url=None):
    """fig and media tag caption may have supplementary material"""
    if supp_tags is None or len(supp_tags) == 0:
        return ''
    for supp_tag in supp_tags:
        if supp_tag.tag == 'fig':
            for caption in supp_tag.findall('./caption'):
                caption.text = caption.text + ' (Supplementary Materials available at ' + base_url + '/media)'
        elif supp_tag.tag == 'media':
            for caption in supp_tag.findall('./caption'):
                caption.text = caption.text + ' (Supplementary Materials available at ' + base_url + '/media)'
    return ''

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        for schema in schemas:
            if schema == os.path.abspath(schema):
                schema_file = schema
            else:
                schema_file = os.path.join(self.paths.schemas, schema)

            if os.path.isfile(schema_file):
                # Absolute path: use it.
                yield schema_file
            elif skip_missing_schemas:
                logger.warning("Unable to locate schema %s at %s", schema, schema_file)
            else:
                raise PathError("Unable to locate schema %s at %s" % (schema, schema_file))

def _locate_schemas(self, schemas, skip_missing_schemas):
        """Locate all schemas (look in openldap store).

        If skip_missing_schemas is True, ignore missing schemas;
        otherwise, raise.
        """
        if schemas is None:
            schemas = []
        schemas = [s for s in schemas if s not in self.schemas]
        if schemas:
            for schema in schemas:
                if schema in self.schemas:
                    continue
                if skip_missing_schemas:
                    continue
                raise LDAPSchemaError(
                    "schema %r not found in openldap store" % schema)

            self.schemas.extend(schemas)

            if self.schemas:
                self.schema_dn = "cn=schema,cn=config"
                self.schema_dn = self._get_dn(self.schema_dn)
                if not self.schema_dn:
                    raise LDAPSchemaError(
                        "cn=schema,cn=config not found in openldap store")

