def restore(self, fade=False):
        """Restore the state of a device to that which was previously saved.

        For coordinator devices restore everything. For slave devices
        only restore volume etc., not transport info (transport info
        comes from the slave's coordinator).

        Args:
            fade (bool): Whether volume should be faded up on restore.
        """

        try:
            if self.is_coordinator:
                self._restore_coordinator()
        finally:
            self._restore_volume(fade)

        # Now everything is set, see if we need to be playing, stopped
        # or paused ( only for coordinators)
        if self.is_coordinator:
            if self.transport_state == 'PLAYING':
                self.device.play()
            elif self.transport_state == 'STOPPED':
                self.device.stop()

def send(self, url, data, headers):
        """
        Sends a request to an SQS queue -- to be later popped off
        later for submission into Sentry.
        Note: This will simply raise any Boto ClientErrors that are encountered.
        """
        response = self.sqs_client.send_message(
            QueueUrl=url,
            MessageAttributes={
                'timestamp': {
                    'StringValue': str(datetime.datetime.utcnow()),
                    'DataType': 'String'
                }
            },
            MessageBody=data,
            MessageGroupId='sentry-events',
        )

        return response

def _md5_compare(self, file_path, checksum, block_size=2 ** 13):
        """Compare a given MD5 checksum with one calculated from a file."""
        with closing(self._tqdm(desc="MD5 checksumming", total=getsize(file_path), unit="B",
                                unit_scale=True)) as progress:
            md5 = hashlib.md5()
            with open(file_path, "rb") as f:
                while True:
                    block_data = f.read(block_size)
                    if not block_data:
                        break
                    md5.update(block_data)
                    progress.update(len(block_data))
            return md5.hexdigest().lower() == checksum.lower()

def _md5_compare(self, file_path, checksum, block_size=2 ** 13):
        """Compare a given MD5 checksum with one calculated from a file."""
        with open(file_path, "rb") as fp:
            md5 = hashlib.md5()
            while True:
                data = fp.read(block_size)
                if not data:
                    break
                md5.update(data)
            return md5.hexdigest() == checksum

def parse_bookmark_data (data):
    """Return iterator for bookmarks of the form (url, name, line number).
    Bookmarks are not sorted.
    """
    name = None
    lineno = 0
    for line in data.splitlines():
        lineno += 1
        line = line.strip()
        if line.startswith("NAME="):
            name = line[5:]
        elif line.startswith("URL="):
            url = line[4:]
            if url and name is not None:
                yield (url, name, lineno)
        else:
            name = None

def parse_bookmark_data (data):
    """Return iterator for bookmarks of the form (url, name, line number).
    Bookmarks are not sorted.
    """
    for line in data.splitlines():
        if line.startswith('#'): continue
        if not line: continue
        try:
            url, name, line = line.split(' ', 2)
            yield url, name, int(line)
        except ValueError:
            raise ValueError("Bad bookmark file: %r" % line)

def _get_or_create_run(build):
    """Gets a run for a build or creates it if it does not exist."""
    runs = build.runs
    for run in runs:
        if run.status == 'active':
            return run
    return runs.create()

def update_project(self, project_id, name=None, description=None,
                       reference_language=None):
        """
        Updates project settings (name, description, reference language)
        If optional parameters are not sent, their respective fields are not updated.
        """
        kwargs = {}
        if name is not None:
            kwargs['name'] = name
        if description is not None:
            kwargs['description'] = description
        if reference_language is not None:
            kwargs['reference_language'] = reference_language

        data = self._run(
            url_path="projects/update",
            id=project_id,
            **kwargs
        )
        return data['result']['project']['id']

def update_project(self, project_id, name=None, description=None,
                       reference_language=None):
        """
        Updates project settings (name, description, reference language)
        If optional parameters are not sent, their respective fields are not updated.
        """
        project = self.get_project(project_id)
        if name:
            project['name'] = name
        if description:
            project['description'] = description
        if reference_language:
            project['reference_language'] = reference_language
        return self._update('projects/%s' % project_id, project)

def check_for_errors(self):
        """Check connection and channel for errors.

        :raises AMQPChannelError: Raises if the channel encountered an error.
        :raises AMQPConnectionError: Raises if the connection
                                     encountered an error.
        :return:
        """
        try:
            self._connection.check_for_errors()
        except AMQPConnectionError:
            self.set_state(self.CLOSED)
            raise

        if self.exceptions:
            exception = self.exceptions[0]
            if self.is_open:
                self.exceptions.pop(0)
            raise exception

        if self.is_closed:
            raise AMQPChannelError('channel was closed')

def check_for_errors(self):
        """Check connection and channel for errors.

        :raises AMQPChannelError: Raises if the channel encountered an error.
        :raises AMQPConnectionError: Raises if the connection
                                     encountered an error.
        :return:
        """
        if self._channel.is_closed:
            raise AMQPChannelError(
                'Channel has been closed. Reason: {0}'.format(
                    self._channel.close_reason
                )
            )

        if self._connection.is_closed:
            raise AMQPConnectionError(
                'Connection has been closed. Reason: {0}'.format(
                    self._connection.close_reason
                )
            )

def split_fasta(f, id2f):
    """
    split fasta file into separate fasta files based on list of scaffolds
    that belong to each separate file
    """
    opened = {}
    for seq in parse_fasta(f):
        id = seq[0].split('>')[1].split()[0]
        if id not in id2f:
            continue
        fasta = id2f[id]
        if fasta not in opened:
            opened[fasta] = '%s.fa' % fasta
        seq[1] += '\n'
        with open(opened[fasta], 'a+') as f_out:
            f_out.write('\n'.join(seq))

def split_fasta(f, id2f):
    """
    split fasta file into separate fasta files based on list of scaffolds
    that belong to each separate file
    """
    for line in open(f):
        if line.startswith('>'):
            if line.strip()[1:] not in id2f:
                print('%s not found in scaffold list' % line.strip()[1:])
                exit()
            out = open(id2f[line.strip()[1:]], 'w')
        else:
            out.write(line)
    out.close()

def validate_busy(func, *args, **kwargs):
    """
    A decorator that raises an exception if the specified target is busy.

    Expects the target ID to be either the 'target_id' param in kwargs,
    or the first positional parameter.

    Raises a TargetBusyException if the target does not exist.
    """
    def inner(self, *args, **kwargs):
        # find the target param
        target_id = None
        if 'target_id' in kwargs and kwargs['target_id'] != None:
            target_id = kwargs['target_id']
        else:
            target_id = 0

        # if there was a target specified, ensure it's not busy
        if self.target_is_busy(target_id):
            raise TargetBusyException()

        # call the function
        return func(self, *args, **kwargs)
    return inner

def validate_busy(func, *args, **kwargs):
    """
    A decorator that raises an exception if the specified target is busy.

    Expects the target ID to be either the 'target_id' param in kwargs,
    or the first positional parameter.

    Raises a TargetBusyException if the target does not exist.
    """
    from .exceptions import TargetBusyException

    target_id = kwargs.get("target_id")

    if target_id is None:
        target_id = args[0]

    if isinstance(target_id, str):
        target = func(target_id, *args[1:], **kwargs)
    else:
        target = func(*args, **kwargs)

    if target.busy:
        raise TargetBusyException(
            f"Target {target_id} is currently busy with {target.busy_with}"
        )

    return target

def split_func_name_args_params_handle(tokens):
    """Process splitting a function into name, params, and args."""
    for idx, token in enumerate(tokens):
        if token.is_type('function_name'):
            func_name = token.get_text()
        elif token.is_type('function_parameter'):
            func_param = token.get_text()
        elif token.is_type('function_argument'):
            func_arg = token.get_text()
        elif token.is_type('function_handle'):
            func_handle = token.get_text()

    return func_name, func_param, func_arg, func_handle

def revoke_session(self, sid='', token=''):
        """
        Mark session as revoked but also explicitly revoke all issued tokens

        :param token: any token connected to the session
        :param sid: Session identifier
        """
        if not sid:
            if token:
                sid = self.handler.sid(token)
            else:
                raise ValueError('Need one of "sid" or "token"')

        for typ in ['access_token', 'refresh_token', 'code']:
            try:
                self.revoke_token(self[sid][typ], typ)
            except KeyError:  # If no such token has been issued
                pass

        self.update(sid, revoked=True)

def get_files():
    """
    Read all the template's files
    """

    files_root = path.join(path.dirname(__file__), 'files')

    for root, dirs, files in walk(files_root):
        rel_root = path.relpath(root, files_root)

        for file_name in files:
            try:
                f = open(path.join(root, file_name), 'r', encoding='utf-8')
                with f:
                    yield rel_root, file_name, f.read(), True
            except UnicodeError:
                f = open(path.join(root, file_name), 'rb')
                with f:
                    yield rel_root, file_name, f.read(), False

def get_files():
    """
    Read all the template's files
    """
    templates = []
    for root, dirs, files in os.walk(os.path.dirname(__file__)):
        templates.extend(
            [os.path.join(root, f) for f in files if not f.startswith('.')]
        )
    return templates

def from_dict(cls, val):
        """Creates dict2 object from dict object

        Args:
            val (:obj:`dict`): Value to create from

        Returns:
            Equivalent dict2 object.
        """
        if isinstance(val, dict2):
            return val

        elif isinstance(val, dict):
            res = cls()
            for k, v in val.items():
                res[k] = cls.from_dict(v)
            return res

        elif isinstance(val, list):
            res = []
            for item in val:
                res.append(cls.from_dict(item))
            return res
        else:
            return val

def process_shell(self, creator, entry, config):
        """Processing a shell entry."""
        self.logger.info("Processing Bash code: start")

        output = []
        shell = creator(entry, config)
        for line in shell.process():
            output.append(line)
            self.logger.info(" | %s", line)

        if shell.success:
            self.logger.info("Processing Bash code: finished")
            return {'success': True, 'output': output}

        for line in self.run_cleanup(config.env, shell.exit_code):
            output.append(line)

        self.logger.error("Pipeline has failed: leaving as soon as possible!")
        self.event.failed()
        return {'success': False, 'output': output}

def process_shell(self, creator, entry, config):
        """Processing a shell entry."""
        if not entry.get('shell'):
            return

        shell = entry.get('shell')
        if not isinstance(shell, dict):
            raise Exception('Shell entry must be a dictionary.')

        if not shell.get('id'):
            raise Exception('Shell entry must contain an ID.')

        # The shell entry should be in the same format as a plugin entry.
        shell['type'] = 'shell'
        shell['creator'] = creator
        shell['name'] = shell.get('id')
        shell['description'] = shell.get('description')

        if not shell.get('file'):
            raise Exception('Shell entry must contain a file.')

        if shell['file'][-3:] != '.sh':
            raise Exception('Shell entry must contain a shell script.')

        shell['script'] = self.get_file_content(shell['file'])

        # Check if the shell already exists in the configuration.
        if self.shell_exists(config, shell['id']):
            raise Exception('Shell ID already exists.')

        config['shells'].append(shell)

def assign_variable_names(self):
        """
        Assign default names to all variables.

        :return: None
        """

        for var in self._variables:
            if isinstance(var, SimStackVariable):
                if var.name is not None:
                    continue
                if var.ident.startswith('iarg'):
                    var.name = 'arg_%x' % var.offset
                else:
                    var.name = 's_%x' % (-var.offset)
                    # var.name = var.ident
            elif isinstance(var, SimRegisterVariable):
                if var.name is not None:
                    continue
                var.name = var.ident

def assign_variable_names(self):
        """
        Assign default names to all variables.

        :return: None
        """
        for i, var in enumerate(self.variables):
            if var.name is None:
                var.name = 'X' + str(i + 1)

def disconnect(self, connection):
        """
        Removes a subscriber connection, ensuring that any pending commands get requeued.

        @param connection: The client connection to unsubscribe.
        @type connection: L{coilmq.server.StompConnection}
        """
        self.log.debug("Disconnecting %s" % connection)
        if connection in self._pending:
            pending_frame = self._pending[connection]
            self.store.requeue(pending_frame.headers.get(
                'destination'), pending_frame)
            del self._pending[connection]

        for dest in list(self._queues.keys()):
            if connection in self._queues[dest]:
                self._queues[dest].remove(connection)
            if not self._queues[dest]:
                # This won't trigger RuntimeError, since we're using keys()
                del self._queues[dest]

def disconnect(self, connection):
        """
        Removes a subscriber connection, ensuring that any pending commands get requeued.

        @param connection: The client connection to unsubscribe.
        @type connection: L{coilmq.server.StompConnection}
        """
        self.server.remove_subscriber(connection)
        if self.server.config.debug:
            self.server.logger.debug(
                "disconnect: client %s" % (connection.client_id,))

def catch_raise_api_exception():
    """Context manager that translates upstream API exceptions."""
    try:
        yield
    except _ApiException as exc:
        detail = None
        fields = None

        if exc.body:
            try:
                # pylint: disable=no-member
                data = json.loads(exc.body)
                detail = data.get("detail", None)
                fields = data.get("fields", None)
            except ValueError:
                pass

        detail = detail or exc.reason

        raise ApiException(
            exc.status, detail=detail, headers=exc.headers, body=exc.body, fields=fields
        )

def catch_raise_api_exception():
    """Context manager that translates upstream API exceptions."""
    # TODO: handle errors that are not APIErrors
    # TODO: handle errors that are APIErrors but do not contain
    #       a status_code or a message

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except APIError as err:
                if err.status_code == 404:
                    raise NotFoundError(err.message)
                raise

        return wrapper

    return decorator

def execute(self, logical_form: str):
        """Executes a logical form, using whatever predicates you have defined."""
        if not hasattr(self, '_functions'):
            raise RuntimeError("You must call super().__init__() in your Language constructor")
        logical_form = logical_form.replace(",", " ")
        expression = util.lisp_to_nested_expression(logical_form)
        return self._execute_expression(expression)

def set_properties(self, eid, value, idx='*'):
        """
        Set the value and/or attributes of an xml element, marked with the matching eid attribute, using the
        properties of the specified object.
        """
        if value.__class__ not in Template.class_cache:
            props = []
            for name in dir(value.__class__):
                prop = getattr(value.__class__, name)
                if type(prop) == property and hasattr(prop, 'fget'):
                    props.append((name, prop))
            Template.class_cache[value.__class__] = props
        for (name, prop) in Template.class_cache[value.__class__]:
            new_eid = ''.join([eid, ':', name])
            self.set_value(new_eid, prop.fget(value), idx)
            self.set_attribute(eid, name, prop.fget(value), idx)

def prep_jid(nocache=False, passed_jid=None):
    """
    Return a job id and prepare the job id directory
    This is the function responsible for making sure jids don't collide (unless
    its passed a jid)
    So do what you have to do to make sure that stays the case
    """
    if passed_jid is None:
        jid = salt.utils.jid.gen_jid(__opts__)
    else:
        jid = passed_jid

    cb_ = _get_connection()

    try:
        cb_.add(six.text_type(jid),
               {'nocache': nocache},
               ttl=_get_ttl(),
               )
    except couchbase.exceptions.KeyExistsError:
        # TODO: some sort of sleep or something? Spinning is generally bad practice
        if passed_jid is None:
            return prep_jid(nocache=nocache)

    return jid

def teardown(self):
        """
        Tears down the instance, removing any remaining sessions that this instance has created.

        The instance must not be used after this method has been called.
        """
        with self._teardown_lock:
            if not self._teardown_called:
                self._teardown_called = True
                if len(self._acquiring_session_ids) > 0:
                    logger.info(
                        f"Destroying all sessions that have not acquired keys: {self._acquiring_session_ids}...")
                for session_id in self._acquiring_session_ids:
                    try:
                        self.consul_client.session.destroy(session_id=session_id)
                        logger.debug(f"Destroyed: {session_id}")
                    except requests.exceptions.ConnectionError as e:
                        logger.debug(f"Exception: {e}")
                        logger.warning(f"Could not connect to Consul to clean up session {session_id}")
                atexit.unregister(self.teardown)

def _is_child_wikicode(self, obj, recursive=True):
        """Return whether the given :class:`.Wikicode` is a descendant."""
        def deref(nodes):
            if isinstance(nodes, _ListProxy):
                return nodes._parent  # pylint: disable=protected-access
            return nodes

        target = deref(obj.nodes)
        if target is deref(self.nodes):
            return True
        if recursive:
            todo = [self]
            while todo:
                code = todo.pop()
                if target is deref(code.nodes):
                    return True
                for node in code.nodes:
                    todo += list(node.__children__())
        return False

def _is_child_wikicode(self, obj, recursive=True):
        """Return whether the given :class:`.Wikicode` is a descendant."""
        if recursive:
            for child in obj.children:
                if _is_child_wikicode(child):
                    return True
        return self == obj

def verify(self, string_version=None):
        """
        Check that the version information is consistent with the VCS
        before doing a release. If supplied with a string version,
        this is also checked against the current version. Should be
        called from setup.py with the declared package version before
        releasing to PyPI.
        """
        if string_version and string_version != str(self):
            raise Exception("Supplied string version does not match current version.")

        if self.dirty:
            raise Exception("Current working directory is dirty.")

        if self.release != self.expected_release:
            raise Exception("Declared release does not match current release tag.")

        if self.commit_count !=0:
            raise Exception("Please update the VCS version tag before release.")

        if self._expected_commit not in [None, "$Format:%h$"]:
            raise Exception("Declared release does not match the VCS version tag")

