def merge_deployment_data(dict1: DeployedContracts, dict2: DeployedContracts) -> DeployedContracts:
    """ Take contents of two deployment JSON files and merge them

    The dictionary under 'contracts' key will be merged. The 'contracts'
    contents from different JSON files must not overlap. The contents
    under other keys must be identical.
    """
    if not isinstance(dict1, dict) or not isinstance(dict2, dict):
        raise ValueError('Both arguments must be dictionaries')

    if dict1.get('contracts', None) is None or dict2.get('contracts', None) is None:
        raise ValueError('Both arguments must have "contracts" key')

    if dict1['contracts'] is None or dict2['contracts'] is None:
        raise ValueError('Both "contracts" keys must contain something')

    if not isinstance(dict1['contracts'], dict) or not isinstance(dict2['contracts'], dict):
        raise ValueError('Both "contracts" keys must be dictionaries')

    if not dict1['contracts'].keys() == dict2['contracts'].keys():
        raise ValueError('Both "contracts" keys must have same keys')

    return {
        'contracts': {**dict1['contracts'], **dict2['contracts']},
        'metadata': {**dict1['metadata'], **dict2['metadata']}
    }

def poi_coords(poi_id, *, raw=False):
    """
    DVB Map Coordinates
    (GET https://www.dvb.de/apps/map/coordinates)

    :param poi_id: Id of poi
    :param raw: Return raw response
    :return: Coordinates of poi
    """
    try:
        r = requests.get(
            url='https://www.dvb.de/apps/map/coordinates',
            params={
                'id': poi_id,
            },
        )
        if r.status_code == 200:
            response = json.loads(r.content.decode('utf-8'))
        else:
            raise requests.HTTPError('HTTP Status: {}'.format(r.status_code))
    except requests.RequestException as e:
        print('Failed to access DVB map coordinates app. Request Exception', e)
        response = None

    if response is None or raw:
        return response

    coords = [int(i) for i in response.split('|')]
    lat, lng = gk4_to_wgs(coords[0], coords[1])
    return {
        'lat': lat,
        'lng': lng
    }

def poi_coords(poi_id, *, raw=False):
    """
    DVB Map Coordinates
    (GET https://www.dvb.de/apps/map/coordinates)

    :param poi_id: Id of poi
    :param raw: Return raw response
    :return: Coordinates of poi
    """
    r = requests.get(
        "https://www.dvb.de/apps/map/coordinates",
        params={"poi": poi_id}
    )

    if raw:
        return r

    return r.json()

